//! Typed views of the target's embedded artifacts, with their original cfg gates.
//!
//! Storage stays static; declarations only map the generated bytes into views.
//! The parent composes these with derived data in [`super::FixedTarget`].

use sensei_shared::RowAssignment;

use crate::native::curve::VestaAffine;
use crate::native::field::Fp;
use crate::native::fixed_columns::{
    FIXED_TUPLE_ASSIGNMENTS, FIXED_TUPLE_COUNT, TUPLE_FIXED_COLUMNS,
};
#[cfg(embed_gate_selectors)]
use crate::native::generated_expressions::PREPARED_GATE_SELECTOR_ROW;
#[cfg(any(
    embed_fixed_cosets,
    embed_sigma_cosets,
    embed_gate_selectors,
    embed_boundaries
))]
use sensei_shared::EXTENDED_N;
#[cfg(any(embed_fixed_coefficients, embed_fixed_cosets))]
use sensei_shared::FIXED_COLUMNS;
#[cfg(embed_instance_bases)]
use sensei_shared::INSTANCE_VALUE_COUNT;
use sensei_shared::{N, PERMUTATION_COLUMN_COUNT};

#[cfg(embed_fixed_coefficients)]
crate::static_data::embed_array! {
    /// Montgomery-form coefficients of the 29 fixed polynomials, one row of
    /// the outer array per column.
    pub(super) static FIXED_COEFFICIENTS: [[Fp; N]; FIXED_COLUMNS] = artifact_path!(fixed_coefficients);
}

#[cfg(embed_sigma_coefficients)]
crate::static_data::embed_array! {
    /// Montgomery-form coefficients of the 15 permutation-sigma polynomials,
    /// one row of the outer array per column.
    pub(super) static SIGMA_COEFFICIENTS: [[Fp; N]; PERMUTATION_COLUMN_COUNT] = artifact_path!(sigma_coefficients);
}

#[cfg(embed_fixed_cosets)]
crate::static_data::embed_array! {
    /// Extended-coset evaluations of the 29 fixed polynomials, one row of
    /// the outer array per column.
    pub(super) static FIXED_COSETS: [[Fp; EXTENDED_N]; FIXED_COLUMNS] = artifact_path!(fixed_cosets);
}

#[cfg(embed_sigma_cosets)]
crate::static_data::embed_array! {
    /// Extended-coset evaluations of the 15 permutation-sigma polynomials,
    /// one row of the outer array per column.
    pub(super) static SIGMA_COSETS: [[Fp; EXTENDED_N]; PERMUTATION_COLUMN_COUNT] = artifact_path!(sigma_cosets);
}

// Keep this filename in sync with the complete-selector output in build.rs.
#[cfg(embed_gate_selectors)]
crate::static_data::embed_array! {
    /// The prepared fixed-only gate selectors of every extended-coset row,
    /// in fused-kernel consumption order.
    pub(super) static GATE_SELECTORS: [[Fp; PREPARED_GATE_SELECTOR_ROW]; EXTENDED_N] = concat!(env!("OUT_DIR"), "/gate-selectors-complete.", udon::stored_form!(), ".pod");
}

crate::static_data::embed_array! {
    /// The distinct nonzero row tuples of fixed columns 3 through 11, in
    /// dictionary order of first reference.
    pub(super) static FIXED_TUPLES: [[Fp; TUPLE_FIXED_COLUMNS]; FIXED_TUPLE_COUNT] = artifact_path!(fixed_tuples);
}

crate::static_data::embed_array! {
    /// The sparse row assignments into [`FIXED_TUPLES`], in strictly
    /// increasing row order.
    pub(super) static TUPLE_ASSIGNMENTS: [RowAssignment; FIXED_TUPLE_ASSIGNMENTS] =
        artifact_path!(tuple_assignments);
}

crate::static_data::embed_array! {
    /// The permutation as column-major target-cell indices `column * N + row`
    /// over the 15 permutation columns: a bijection on the 30,720 cells.
    pub(super) static SIGMA_MAP: [[u16; N]; PERMUTATION_COLUMN_COUNT] =
        artifact_path!(sigma_map);
}

#[cfg(embed_window_tables)]
crate::static_data::embed_array! {
    /// The joint `(x, y, u)` fixed-base window entries of every
    /// multiplication region, flat in `FIXED_BASE_REGIONS` order and consumed
    /// by the witness writer. Generated into `OUT_DIR` by `build.rs` through
    /// the shared `sensei-shared` construction (the same code the prover
    /// runs at load when this artifact is disabled); its exact bytes are
    /// pinned below.
    pub(crate) static WINDOW_TABLES: [[sensei_shared::WindowTableEntry;
        sensei_shared::fixed_bases::FIXED_BASE_WINDOW_SIZE as usize];
        sensei_shared::fixed_bases::FIXED_BASE_TOTAL_WINDOWS] = artifact_path!(window_tables);
}

crate::static_data::embed_array! {
    /// For every fixed-base multiplication window (flat in
    /// `FIXED_BASE_REGIONS` order) and each of its eight digit choices, the
    /// Vesta point `x(window, digit) · G_row` over the window's Lagrange
    /// base: the advice commitment adds the selected point instead of
    /// committing the full-width `x` cell. Generated into `OUT_DIR` by
    /// `build.rs` from the pinned SRS and the shared window-table
    /// construction; its exact bytes are pinned below.
    pub(super) static FIXED_WINDOW_X_BASES: [VestaAffine;
        sensei_shared::fixed_bases::FIXED_BASE_TOTAL_WINDOWS
            * sensei_shared::fixed_bases::FIXED_BASE_WINDOW_SIZE as usize] =
        artifact_path!(fixed_window_x_bases);
}

crate::static_data::embed_array! {
    /// The `y` family of [`FIXED_WINDOW_X_BASES`]: `y(window, digit) · G_row`
    /// for every fixed-base window and digit, consumed by the `Y_COLUMN`
    /// commitment. Its exact bytes are pinned below.
    pub(super) static FIXED_WINDOW_Y_BASES: [VestaAffine;
        sensei_shared::fixed_bases::FIXED_BASE_TOTAL_WINDOWS
            * sensei_shared::fixed_bases::FIXED_BASE_WINDOW_SIZE as usize] =
        artifact_path!(fixed_window_y_bases);
}

crate::static_data::embed_array! {
    /// The `u` family of [`FIXED_WINDOW_X_BASES`]: `u(window, digit) · G_row`
    /// for every fixed-base window and digit, consumed by the `U_COLUMN`
    /// commitment. Its exact bytes are pinned below.
    pub(super) static FIXED_WINDOW_U_BASES: [VestaAffine;
        sensei_shared::fixed_bases::FIXED_BASE_TOTAL_WINDOWS
            * sensei_shared::fixed_bases::FIXED_BASE_WINDOW_SIZE as usize] =
        artifact_path!(fixed_window_u_bases);
}

#[cfg(embed_instance_bases)]
crate::static_data::embed_array! {
    /// Transposed coefficient bases of the Lagrange polynomials at the
    /// populated instance rows, one row per coefficient degree. Generated
    /// into `OUT_DIR` by `build.rs` with the same geometric coefficient
    /// progressions the prover writes at load when this artifact is disabled.
    pub(super) static INSTANCE_BASES: [[Fp; INSTANCE_VALUE_COUNT]; N] = artifact_path!(instance_bases);
}

#[cfg(embed_boundaries)]
crate::static_data::embed_array! {
    /// The extended-coset boundary polynomials, in `l_0`, `l_last`,
    /// active-row-mask order. Generated into `OUT_DIR` by `build.rs` with the
    /// same transforms the prover runs at load when this artifact is
    /// disabled.
    pub(super) static BOUNDARY_POLYNOMIALS: [[Fp; EXTENDED_N]; 3] = artifact_path!(boundaries);
}
